public int findLargestSubstring(List<String> strings) {
    // Helper function to check if a string is a substring of another string
    boolean isSubstring(String str, String substr) {
        int index = str.indexOf(substr);
        return index != -1;
    }

    // Helper function to iterate through each string and its inverse
    void checkStrings(List<String> strings) {
        for (String s : strings) {
            String reversed = new StringBuilder(s).reverse().toString();
            checkSubstrings(s, s, reversed);
            checkSubstrings(s, reversed, s);
        }
    }

    // Helper function to check for substrings with both original and reversed strings
    void checkSubstrings(String s, String original, String reversed) {
        if (isSubstring(s, original) && isSubstring(s, reversed)) {
            return;
        }
        if (isSubstring(reversed, original) && isSubstring(reversed, s)) {
            return;
        }
    }

    // Main function to find the largest string
    public int findLargestSubstring(List<String> strings) {
        checkStrings(strings);
        int largest = 0;
        for (String s : strings) {
            largest = Math.max(largest, s.length());
        }
        return largest;
    }
}

