}

public static String appx(String word1, String word2) {
    int numCommonChars = 0;
    for (char c : word1.toCharArray()) {
        if (word2.indexOf(c) != -1) {
            numCommonChars++;
        }
    }
    double numCharsTotal = word1.length() + word2.length();
    Double fraction = (double) numCommonChars / numCharsTotal;
    fraction = Math.round(fraction * 1000) / 1000.0;
    return "appx(" + word1 + ", " + word2 + ") = " + fraction;
}

