    int_trimFirst = 0.05 * arr.length;
    int_trimLast = arr.length - 1 - 0.05 * arr.length;
    int trimmedSize = arr.length - 2 * (int_trimFirst + int_trimLast);
    double sum = 0;
    for (int i = int_trimFirst + 1; i < arr.length - int_trimLast - 1; i++) {
        sum += arr[i];
    }
    return sum / trimmedSize;
}

public double trimMean(int[] arr) {
