}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Input array is empty");
    }

    int n = arr.length;
    int half = n / 2 - 2; // Calculate the index for the middle element (excluding the 5% tails)
    Arrays.sort(arr);

    double sum = 0;
    for (int i = half; i < n - half; i++) {
        sum += arr[i];
    }

    // Round the sum to 10^-5 and divide by the remaining elements
    return Math.round(sum / (n - 2 * half) * 100000d) / 100000d;
}

public double trimMean(int[] arr) {
