    int lowIndex = arr.length * 5 / 20; // Calculate the index to remove 5% from the left
    int highIndex = arr.length - arr.length * 5 / 20; // Calculate the index to remove 5% from the right
    double sum = 0;
    for (int i = lowIndex + 1; i < highIndex; i++) {
        sum += arr[i]; // Add the remaining elements to the sum
    }
    return sum / (highIndex - lowIndex - 1); // Calculate the mean
}

