public String sortString(String s) {
    StringBuilder sb = new StringBuilder();
    String[] chars = s.split("");
    int[] frequency = new int[256];

    // Count the frequency of each character
    for (String c : chars) {
        frequency[c.charAt(0)]++;
    }

    int start = 0;
    int end = chars.length - 1;

    // Process characters in ascending order
    while (start <= end) {
        // Append the smallest character encountered so far
        for (int i = 0; i < 256; i++) {
            if (frequency[i] > 0) {
                sb.append((char) i);
                frequency[i]--;
                break;
            }
        }

        // Process the largest character encountered so far
        for (int i = 255; i >= 0; i--) {
            if (frequency[i] > 0) {
                sb.append((char) i);
                frequency[i]--;
                break;
            }
        }
    }

    return sb.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    Map<Character, Integer> charCounts = new LinkedHashMap<>();
    int stringSize = s.length();

    // Count occurrences of each character
    for (char c : s.toCharArray()) {
        charCounts.put(c, charCounts.getOrDefault(c, 0) + 1);
    }

    while (stringSize > 0) {
        // Append smallest character
        for (Map.Entry<Character, Integer> entry : charCounts.entrySet()) {
            if (entry.getValue() > 0) {
                result.append(entry.getKey());
                entry.setValue(entry.getValue() - 1);
                stringSize--;
                break;
            }
        }

        // Append largest character
        for (Map.Entry<Character, Integer> entry : charCounts.entrySet()) {
            if (entry.getValue() > 0) {
                result.append(entry.getKey());
                entry.setValue(entry.getValue() - 1);
                stringSize--;
                break;
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    StringBuffer sortedString = new StringBuffer();
    StringBuilder remainingChars = new StringBuilder(s);

    while (!remainingChars.isEmpty()) {
        char smallest = '9'; // Assuming the character '9' is greater than the highest ASCII value
        char largest = '0'; // Assuming the character '0' is lower than the lowest ASCII value

        for (char c : remainingChars) {
            if (c < smallest) {
                smallest = c;
            }
            if (c > largest) {
                largest = c;
            }
        }

        // Append the smallest character
        sortedString.append(smallest);
        remainingChars.deleteCharAt(remainingChars.indexOf(smallest));

        if (remainingChars.isEmpty()) {
            break;
        }

        // Append the largest character
        sortedString.append(largest);
        remainingChars.deleteCharAt(remainingChars.indexOf(largest));
    }

    return sortedString.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    List<Character> available = new ArrayList<>();
    for (char c: s.toCharArray()) {
        available.add(c);
    }

    StringBuilder result = new StringBuilder();
    while (!available.isEmpty()) {
        char minChar = available.get(0);
        char maxChar = available.get(available.size() - 1);

        for (int i = 0; i < available.size(); i++) {
            char c = available.get(i);
            if (c < minChar) {
                minChar = c;
            }
            if (c > maxChar) {
                maxChar = c;
            }
        }

        result.append(minChar);
        available.remove(available.indexOf(minChar));
        if (!available.isEmpty()) {
            result.append(maxChar);
            available.remove(available.indexOf(maxChar));
        }
    }

    return result.toString();
}

