public int findMinFibonacciNumbers(int k) {
    int f1 = 1, f2 = 1, num = 0;
    while (f2 <= k) {
        if (f2 == k)
            return num + 1;
        int temp = f2;
        f2 = f1 + f2;
        f1 = temp;
        num++;
    }
    return -1; // If no Fibonacci number sums up to k
}

public int findMinFibonacciNumbers(int k) {
    Set<Integer> fibSet = new HashSet<>();
    fibSet.add(0);
    fibSet.add(1);
    int nextFib = 1;

    while (nextFib < k) {
        fibSet.add(nextFib);
        nextFib = fibSet.last() + fibSet.get(fibSet.size() - 2);
    }

    int count = 0;
    while (k > 0) {
        if (fibSet.contains(k)) {
            k -= fibSet.remove(fibSet.size() - 1);
            count++;
        } else {
            int largestFib = fibSet.floor(k);
            k -= largestFib;
            count++;
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
        Set<Integer> fibs = new HashSet<>();
        fibs.add(0);
        fibs.add(1);

        while (true) {
            int latest = fibs.last();
            if (latest * 2 > k) break;
            fibs.add(latest * 2);
            if (latest * 3 > k) break;
            fibs.add(latest * 3);
        }

        int count = 0;
        while (k > 0) {
            if (fibs.contains(k)) {
                count++;
                k -= k;
            } else {
                int prev = findFibonacciBefore(k, fibs);
                count++;
                k -= prev;
            }
        }

        return count;
    }

