public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int i = 26; // 'z' has a value of 26

    while (n > 0 && k > 0) {
        if (k >= i) {
            k -= i;
            result.append((char) ('a' + i - 1));
            i--;
        } else {
            result.append('a');
            k--;
            // Reducing n might not affect the lexicographically smallest string
            n--;
        }
    }

    // If the last character was 'a', it means we need to decrease n
    if (result.length() > 0 && result.charAt(result.length() - 1) == 'a') {
        if (n > 0) {
            result.append('a');
            n--;
        }
    }

    // Reverse the string to get the lexicographically smallest order
    return new String(result.reverse().toString());
}

public String getSmallestString(int n, int k) {
    if (k == 1) {
        return "a";
    }

    StringBuilder sb = new StringBuilder();
    int_remaining_chars = n - 1;
    current_value = 1;

    while (true) {
        if (current_value + remaining_chars >= k) {
            sb.append((char) ('a' + k - 1));
            k = k - (current_value + remaining_chars - k);
            remaining_chars--;
        } else {
            sb.append((char) ('a' + current_value));
            k -= current_value;
            remaining_chars--;
            if (remaining_chars == 0) {
                break;
            }
        }

        current_value++;
    }

    return sb.reverse().toString();
}

