public String getSmallestString(int n, int k) {
    StringBuffer sb = new StringBuffer();
    k -= 1; // We need to subtract 1 because the sum for 'a' is already 1
    for (int i = 0; i < n; i++) {
        sb.append((char) (65 + k % 25)); // 'a' maps to 65, 'b' maps to 66, ..., 'z' maps to 122
        k /= 25; // Reduce k by 25 because each character represents 25 positions
    }
    result = sb.toString();
    return result;
}

public static String getSmallestString(int n, int k) {
    char[] chars = new char[n];
    chars[n-1] = ((char)(k % 26 + 'a'));
    k /= 26;
    char last = chars[n-1];
    for (int i = n - 2; i >= 0; i--) {
        char newChar = ((char)((k % 26 + 'a') - 1 + 'a'));
        if (newChar < last) {
            chars[i] = newChar;
            last = chars[i];
        } else {
            digits += 1;
            while (newChar >= last) {
                last += 1;
            }
            chars[i] = last;
            last = chars[i];
            digits -= 1;
        }
        k /= 26;
        for (int j = 0; j < digits; j++) {
            chars[i] += 'a';
        }
    }
    return new String(chars);
}

