    int[][]_lengths = new int[m][n];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            lengths[i][j] = 1;
        }
    }

    // Calculate lengths for rows
    for (int i = 1; i < m; i++) {
        for (int j = 0; j < n && mat[i][j] == 1; j++) {
            lengths[i][j] = lengths[i-1][j] + 1;
        }
    }

    // Calculate lengths for columns
    for (int j = 1; j < n; j++) {
        for (int i = m-1; i >= 0 && mat[i][j] == 1; i--) {
            lengths[i][j] = lengths[i][j-1] + 1;
        }
    }

    // Calculate lengths for diagonals
    for (int i = 0; i < min(m, n); i++) {
        for (int j = 0; i <= j && i < m && j < n && mat[i][j] == 1; i++, j++) {
            lengths[i][j] = lengths[i-1][j-1] + 1;
        }
    }

    // Calculate lengths for anti-diagonals
    for (int i = m-1; i >= 0; i--) {
        for (int j = 0; i >= j && i < m && j < n && mat[i][j] == 1; i--, j++) {
            lengths[i][j] = lengths[i+1][j-1] + 1;
        }
    }

    int maxLength = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            maxLength = Math.max(maxLength, lengths[i][j]);
        }
    }

