    boolean isPerfectSquare(int num) {
        double sqrt = Math.sqrt(num);
        return sqrt == Math.floor(sqrt);
    }

    // Helper function to generate paths and count the number of valid permutations
    public void generatePaths(int[] A, int currIndex, int count) {
        if (currIndex == A.length) {
            if (isPerfectSquare(A[currIndex - 2] + A[currIndex])) {
                result++;
            }
            return;
        }
        for (int i = currIndex + 1; i < A.length; i++) {
            int temp = A[currIndex];
            A[currIndex] = A[i];
            A[i] = temp;
            generatePaths(A, currIndex + 1, count + 1);
            // Backtrack
            temp = A[currIndex];
            A[currIndex] = A[i];
            A[i] = temp;
        }
    }

    // Start generating paths from each element
    for (int i = 0; i < A.length; i++) {
        generatePaths(A, i, 1);
    }

    return result;
}

