    // Helper function to find the next square permutation
    int findNext[] = new int[n + 1];
    findNext[1] = 0;
    for (int i = 2; i <= n; i++) {
        int j = i, cnt = 0;
        do {
            cnt++;
        } while (!isPerfectSquare.findNext(cnt, cnt * cnt));
        findNext[i] = findNext[cnt] + 1;
    }

    void permute(int[] A, int index, int[] visited) {
        if (index == n) {
            result++;
            return;
        }
        for (int i = 0; i < n; i++) {
            if (visited[i] == 0) {
                visited[i] = 1;
                A[index] = A[i];
                permute(A, index + 1, visited);
                visited[i] = 0;
            }
        }
    }

    boolean isPerfectSquare(int x, int y) {
        int temp = (int)Math.sqrt(y - x * x);
        return temp * temp == y - x * x;
    }

    permute(A, 0, visited);
    return result;
}

