public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) return 0;

    int maxArea = 0;
    int[] leftSmaller = new int[heights.length];
    int[] rightSmaller = new int[heights.length];

    // Initialize leftSmaller array with -1
    for (int i = 0; i < heights.length; i++) {
        leftSmaller[i] = -1;
    }

    // Initialize rightSmaller array with heights.length
    for (int i = heights.length - 1; i >= 0; i--) {
        rightSmaller[i] = heights.length;
    }

    // Process left side to find the nearest smaller element
    for (int i = 1; i < heights.length; i++) {
        int index = i - 1;
        while (index >= 0 && heights[index] >= heights[i]) {
            index = leftSmaller[index];
        }
        if (index != -1) {
            leftSmaller[i] = index;
        }
    }

    // Process right side to find the nearest smaller element
    for (int i = heights.length - 2; i >= 0; i--) {
        int index = i + 1;
        while (index < heights.length && heights[index] >= heights[i]) {
            index = rightSmaller[index];
        }
        if (index != heights.length) {
            rightSmaller[i] = index;
        }
    }

    // Calculate the area of each rectangle and update maxArea
    for (int i = 0; i < heights.length; i++) {
        int width = rightSmaller[i] - leftSmaller[i] - 1;
        maxArea = Math.max(maxArea, heights[i] * width);
    }

    return maxArea;
}

