    int di = 0;
    int dj = 0;
    boolean goDown = true;

    while (index < rows * cols) {
        // Move in the current direction
        int i = di;
        int j = dj;

        while (i < rows && j < cols) {
            results[index++] = mat[i][j];
            i += di;
            j += dj;
