            if (i < rows && j == cols - 1) {
                di++;
            } else if (i == rows - 1) {
                dj++;
                goDown = false;
            }
        } else {
            if (j < cols && i == rows - 1) {
                dj++;
            } else if (j == cols - 1) {
                di--;
                goDown = true;
            }
        }
    }

    return results;
}

