    int col = 0;
    int idx = 0;
    int[] res = new int[r * c]; // holds elements to be returned in the end
    int dir = -1; // 0 for left -> down to right and 1 for top -> bottom to left

    // Traverse all the remaining diagonal elements
    while (idx < (r * c)) {
        q.add(mat[row][col]);
        res[idx++] = q.poll(); // the first element in queue is in the current diagonal

        if (dir == 0) {
            // left -> down to right
            if (col == c - 1) row++;
            else if (row > 0) row--;
            else col++;
        } else {
            // top -> bottom to left
            if (row == r - 1) col++;
            else if (col > 0) col--;
            else row++;
        }

        if (q.isEmpty()) {
            if (dir == 0) col++; // move in right to adjust the direction for the next traversal
            else row++; // move in down to adjust the direction for the next traversal
            dir = -dir; // change the direction
            q.add(mat[row][col]); // start the next diagonal
        }
    }

    return res;
}

public static int findSmallestInteger(int n) {
    // Convert the integer to a list of its digits
    char[] digits = String.valueOf(n).toCharArray();
    int index = -1;

    // Find the first digit that can be swapped to form a smaller number
    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            index = i;
            break;
        }
    }

    if (index == -1) {
        // If no such digit is found, no smaller rearrangement is possible
        return -1;
    }

    // Find the smallest digit in the remaining part of the array that is greater than digits[index]
    int minSwappableDigit = -1;
    for (int i = digits.length - 1; i > index; i--) {
        if (digits[i] > digits[index] && (minSwappableDigit == -1 || digits[i] < digits[minSwappableDigit])) {
            minSwappableDigit = i;
        }
    }

    // Swap the found digits
    char temp = digits[index];
    digits[index] = digits[minSwappableDigit];
    digits[minSwappableDigit] = temp;

    // Sort the remaining part of the array
    Arrays.sort(digits, index + 1, digits.length);

    // Convert the modified array back to an integer
    return Integer.parseInt(new String(digits));
}

public static int findSmallestInteger(int n) {
    String numStr = String.valueOf(n);
    int[] digits = new int[numStr.length()];
    for (int i = 0; i < numStr.length(); i++) {
        digits[i] = Character.getNumericValue(numStr.charAt(i));
    }

    int index = numStr.length() - 1;
    while (index > 0 && digits[index] <= digits[index - 1]) {
        index--;
    }

    if (index == 0) {
        return -1; // Reversing digits would not create a larger integer
    }

    int targetPosition = index - 1;
    for (int i = numStr.length() - 1; i > targetPosition; i--) {
        if (digits[i] > digits[targetPosition]) {
            int temp = digits[i];
            digits[i] = digits[targetPosition];
            digits[targetPosition] = temp;
            break;
        }
    }

    for (int j = index, k = numStr.length() - 1; j < k; j++, k--) {
        int temp = digits[j];
        digits[j] = digits[k];
        digits[k] = temp;
    }

    return Integer.parseInt(String.join("", digits));
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();

    // Ensure the number is greater than itself
    if (n == Integer.parseInt(String.valueOf(digits))) {
        return -1;
    }

    // Sort the digits in ascending order
    Arrays.sort(digits);

    // Move digits from the end to the beginning to find the largest arrangement that is still greater than n
    for (int i = digits.length - 1; i > 0; i--) {
        if (digits[i - 1] < digits[i]) {
            int temp = digits[i];
            digits[i] = digits[i - 1];
            digits[i - 1] = temp;

            // Sort the remaining digits to get the smallest arrangement
            Arrays.sort(digits, i, digits.length);

            return Integer.parseInt(new String(digits));
        }
    }

    // Return -1 if no valid arrangement can be found
    return -1;
}

public static int findSmallestInteger(int n) {
    // Convert the integer to an array of digits
    int[] digits = new int[10];
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
    }

    // Find the position to insert the smallest digit to get the smallest possible number
    int smallestPosition = -1;
    for (int i = 0; i < digits.length; i++) {
        if (digits[i] > 0) {
            smallestPosition = i;
            break;
        }
    }

    // If no position is found, it means the input integer is already sorted in ascending order, and no smallest integer can be formed
    if (smallestPosition == -1) return -1;

    // Find the smallest digit greater than the digit at the smallest position
    int smallestGreater = -1;
    for (int i = 0; i < digits.length; i++) {
        if (i != smallestPosition && digits[i] > digits[smallestPosition]) {
            smallestGreater = i;
            break;
        }
    }

    // Swap the smallest digit greater than the smallest position with the smallest digit at the smallest position
    int temp = digits[smallestPosition];
    digits[smallestPosition] = digits[smallestGreater];
    digits[smallestGreater] = temp;

    // Sort the digits from the smallest position to the end to get the smallest possible number
    Arrays.sort(digits, smallestPosition);

    // Construct the resulting integer
    int result = 0;
    for (int i = 0; i < digits.length; i++) {
        result = result * 10 + digits[i];
    }

    return result;
}

