            }
        }

        return centerSymmetricNumbers;
    }

public static boolean isBoomerang(int[][] points) {
    int len = points.length;
    if (len != 3) {
        throw new IllegalArgumentException("Input should have exactly 3 points");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    int det = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    return det != 0;
}

public static boolean isBoomerang(int[][] points) {
    // Check for collinearity using the determinant method
    // The determinant of the matrix formed by the points should not be zero
    double determinant = points[0][0]*(points[1][1]-points[2][1]) +
                       points[0][1]*(points[2][0]-points[1][0]) +
                       points[1][0]*(points[0][1]-points[2][1]);
    return determinant != 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length < 3) {
        throw new IllegalArgumentException("Input should have at least 3 points");
    }

    int x0 = points[0][0];
    int y0 = points[0][1];
    int x1 = points[1][0];
    int y1 = points[1][1];
    int x2 = points[2][0];
    int y2 = points[2][1];

    int det = (x1 - x0)*(y2 - y0) - (x2 - x0)*(y1 - y0);

    return det != 0;
}

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    return (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) != 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }

    // Check if the points form a triangle
    if (Math.abs(points[0][0] - points[1][0]) == 0 || Math.abs(points[1][0] - points[2][0]) == 0 || Math.abs(points[2][0] - points[0][0]) == 0 ||
        Math.abs(points[0][1] - points[1][1]) == 0 || Math.abs(points[1][1] - points[2][1]) == 0 || Math.abs(points[2][1] - points[0][1]) == 0) {
        return false;
    }

    // Check if the points do not lie on a straight line
    if ((points[0][1] - points[1][1]) * (points[1][0] - points[2][0]) == (points[1][0] - points[0][0]) * (points[2][1] - points[1][1])) {
        return false;
    }

    return true;
}

public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;

    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(uglyNumbers[i2] * 2, Math.min(uglyNumbers[i3] * 3, uglyNumbers[i5] * 5));
        uglyNumbers[i] = nextUgly;

        if (nextUgly == uglyNumbers[i2] * 2) {
            i2++;
        }
        if (nextUgly == uglyNumbers[i3] * 3) {
            i3++;
        }
        if (nextUgly == uglyNumbers[i5] * 5) {
            i5++;
        }
    }

    return uglyNumbers[n - 1];
}

public static int findNthUglyNumber(int n) {
   boolean[] isUgly = new boolean[n]; // Indicates whether a number is ugly
    int[] factors = {2, 3, 5};
    int[] dp = new int[n]; // DP array where dp[i] represents the ith ugly number
    dp[0] = 1;
    int p2 = 0, p3 = 0, p5 = 0; // Pointers to track the multiples of factor 2, 3, 5

    for (int i = 1; i < n; i++) {
        dp[i] = Math.min(dp[p2] * factors[0], Math.min(dp[p3] * factors[1], dp[p5] * factors[2]));
        if (dp[i] == dp[p2] * factors[0]) p2++;
        if (dp[i] == dp[p3] * factors[1]) p3++;
        if (dp[i] == dp[p5] * factors[2]) p5++;
    }

    return dp[n - 1];
}

private static int nextUglyNumber(int current, int numUgly) {
  if (current == numUgly) {
    current *= 2;
  } else if (current == numUgly * 3) {
    current *= 3;
  } else {
    current *= 5;
  }
  return current;
}

public static int nthUglyNumber(int n) {
  if (n == 1) {
    return 1;
  }
  int[] dp = new int[n];
  dp[0] = 1;
  int p2 = 0, p3 = 0, p5 = 0;
  int nextIndex = 1;

  while (nextIndex < n) {
    int nextNumber = Math.min(nextUglyNumber(dp[p2], 2), Math.min(nextUglyNumber(dp[p3], 3), nextUglyNumber(dp[p5], 5)));
    dp[nextIndex] = nextNumber;
    if (nextNumber == nextUglyNumber(dp[p2], 2)) {
      p2++;
    }
    if (nextNumber == nextUglyNumber(dp[p3], 3)) {
      p3++;
    }
    if (nextNumber == nextUglyNumber(dp[p5], 5)) {
      p5++;
    }
    nextIndex++;
  }
  return dp[n - 1];
}

