public static int findNthUglyNumber(int n) {
    if (n <= 0)
        return 0;

    while (true) {
        int candidate = dp[index] * PRIMES[index];
        if (index == 2) {
            dp[index] = candidate;
            index++;
        } else {
            for (int i = 3; i < PRIMES.length; i++) {
                if (candidate % PRIMES[i] == 0) {
                    insert(candidate);
                    dp[index] = candidate;
                    index++;
                    break;
                }
            }
        }

        if (index == n) {
            break;
        }
    }

    return dp[n];
}

public static int calculateEnergy(String s) {
    int maxEnergy = 0;
    int currentEnergy = 1;
    char currentChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentChar = s.charAt(i);
            currentEnergy = 1;
        }
    }

    // Check the last character again in case of the longest substring at the end
    maxEnergy = Math.max(maxEnergy, currentEnergy);

    return maxEnergy;
}

