public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j <= Math.sqrt(i); j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Base cases: return the number of perfect squares needed if n is less than or equal to 1
    if (n <= 3) {
        return n;
    }
    // Initialize a dynamic programming array to store the minimum number of perfect squares needed for each number from 1 to n
    int[] dp = new int[n + 1];
    // Initialize the DP table for numbers less than 1 with a higher effort to manually calculate
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
    }
    // Fill the DP table
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

