public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();
    int start = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == ' ') {
            result.append(new StringBuilder(s.substring(start, i)).reverse().toString() + ' ');
            start = i + 1;
        }
    }

    if (start < s.length()) {
        result.append(new StringBuilder(s.substring(start, s.length())).reverse().toString());
    }

    return result.toString();
}
